  B: [{ name: 'Malphite', role: 'top' }, { name: 'Amumu', role: 'jungle' }, { name: 'Annie', role: 'mid' }, { name: 'Ezreal', role: 'adc' }, { name: 'Morgana', role: 'support' }]
